<template>
  <div class="add-to-cart">
    <!-- 数量大于1会显示加减符号 -->
    <div class="cart-icon cart-icon-big main-color-bg" v-if=" type == 'big' " :class="{'active': num > 0}">
      <i class="icon iconfont cart" @click.stop="add">&#xe628;</i>
      <div class="num-box">
        <i class="icon iconfont main-color-font" @click.stop="minus">&#xe69a;</i>
        <span class="num">{{num}}</span>
        <i class="icon iconfont main-color-font" @click.stop="add">&#xe649;</i>
      </div>
    </div>

    <!-- 数量大于1右上角会显示数量标记 -->
    <div class="cart-icon cart-icon-middle main-color-bg" v-if=" type == 'middle' " @click.stop="add">
      <i class="icon iconfont cart" >&#xe628;</i>
      <span class="select-num" v-show="num">{{num}}</span>
    </div>

    <!-- 数量大于1依旧只显示购物车图标 -->
    <div class="cart-icon cart-icon-small main-color-bg" v-if=" type == 'small' " @click.stop="add">
      <i class="icon iconfont cart">&#xe628;</i>
    </div>
  </div>
</template>

<script>
import PubSub from 'pubsub-js'
export default {
  name: 'AddToCart',
  data () {
    return {
      num: 0,
      leader_id: '',
      toastObj: '',
      checked: 1
    }
  },
  props: ['type', 'goodsId', 'from'],
  created () {
    if (this.$global.goodsNumObj && this.$global.goodsNumObj[this.goodsId]) {
      this.num = this.$global.goodsNumObj[this.goodsId].num
      this.checked = this.$global.goodsNumObj[this.goodsId].checked
    }
    // 订阅购物车数量变化
    PubSub.subscribe('cartInfo', (event, data) => {
      if (this.goodsId == data.goodsId) {
        this.num = data.goodsNum
        this.checked = data.goodsNum == 0 ? 1 : data.checked
      }
      if (this.goodsId === 0) {
        this.checked = data.checked
      }
      if (data.allNeedRefresh) {
        this.num = this.$global.goodsNumObj[this.goodsId] ? this.$global.goodsNumObj[this.goodsId].num : 0
        this.checked = this.$global.goodsNumObj[this.goodsId] ? this.$global.goodsNumObj[this.goodsId].checked : 1
      }
    })
  },
  methods: {
    // 减
    minus () {
      if (this.num == 1) {
        this.$messageBox.confirm('确认从购物车中删除该商品？').then(action => {
          if (action == 'confirm') {
            this.saveCart(this.num * 1 - 1)
          }
        }, () => {})
      } else {
        this.saveCart(this.num * 1 - 1)
      }
    },
    // 加
    add () {
      if (!this.$util.storage.get('ticket')) {
        this.$util.checkLogin()
        return
      }
      this.saveCart(this.num * 1 + 1, 'add')
    },
    // 修改购物车数据
    async saveCart (num, type) {
      let param = {
        leader_id: this.$util.storage.get('leader_id'),
        goods_id: this.goodsId,
        nums: num,
        checked: this.checked,
        noTip: true
      }
      let res = await this.$api.saveCart(param)
      // 抛出错误
      if (!res) return
      // 发布消息：购物车总数变化
      let cartInfo = {
        num: res.all_nums,
        selectNum: res.select_nums,
        money: res.all_money,
        goodsNum: num,
        goodsId: this.goodsId,
        checked: this.checked
      }
      cartInfo.needUpdate = this.from && this.from == 'cart' && (num == 0 || (num == 1 && type == 'add'))
      PubSub.publish('cartInfo', cartInfo)
      if (this.toastObj) {
        this.toastObj.close()
      }
      if (type && type == 'add') {
        this.toastObj = this.$toast({
          message: '添加成功',
          duration: '1500',
          iconClass: 'iconfont icon-success'
        })
      }
      this.$global.goodsNumObj[this.goodsId] = { num: num, checked: this.checked }
      this.$global.goodsNumObj.selectNum = res.select_nums
      this.$global.goodsNumObj.totalNum = res.all_nums
      this.$global.goodsNumObj.totalPrice = res.all_money
      this.num = num
    }
  }
}
</script>

<style lang="stylus">
.add-to-cart
  .cart-icon
    text-align center
    border-radius 50%
    background $color-main
    width 30px
    height 30px
    line-height 30px
    .icon.cart
      vertical-align middle
      color #ffffff
      font-size 22px
    &.cart-icon-big
      .num-box
        color $color-main
        display none
        .num
          color #000
          padding 0 8px
          font-size 16px
          position relative
          top -3px
        .icon
          font-size 26px
          position relative
          &:after
            content ''
            position absolute
            top -5px
            left -5px
            right -5px
            bottom -5px
      &.active
        background #fff !important
        width auto
        .icon.cart
          display none
        .num-box
          display block
    &.cart-icon-middle
      position relative
      .select-num
        width 20px
        height 20px
        text-align center
        line-height 20px
        color #fff
        border-radius 50%
        position absolute
        right -8px
        top -5px
        background #f5391c
    &.cart-icon-small
      width 25px
      height 25px
      line-height 25px
      .icon.cart
        font-size 20px
</style>
