import Vue from 'vue'
import App from './App.vue'
import router from './router'
import 'swiper/dist/css/swiper.css'
import 'mescroll.js/mescroll.min.css'
import 'amfe-flexible'
import api from './api/install'
import util from './common/js/util.js'
import globals from './common/js/globalData'

import 'mint-ui/lib/style.css'
import './static/css/reset.css'
import { IndexList, IndexSection, Cell, Switch, Actionsheet, Range, MessageBox, Toast, Indicator } from 'mint-ui'
Vue.component(IndexList.name, IndexList)
Vue.component(IndexSection.name, IndexSection)
Vue.component(Cell.name, Cell)
Vue.component(Switch.name, Switch)
Vue.component(Actionsheet.name, Actionsheet)
Vue.component(Range.name, Range)
Vue.prototype.$messageBox = MessageBox
Vue.prototype.$toast = Toast

Vue.config.productionTip = false

const wx = require('weixin-js-sdk')
Vue.prototype.$wx = wx
Vue.prototype.$util = util
Vue.prototype.$global = globals
Vue.prototype.$indicator = Indicator
Vue.prototype.wxSdkLoad = false
Vue.use(api)

const app = new Vue({
  router,
  render: h => h(App)
}).$mount('#app')

// ios 设备进入页面则进行js-sdk签名
if (util.checkWeixin() && util.checkIos()) {
  app.$util.getWxconfig()
}
