<template>
  <div id="app">
    <Footer v-show="$route.meta.showFooter" :showBbs="openBbs"/>
    <keep-alive>
      <router-view class="app-content" v-if="$route.meta.keepAlive" :class="{'has-footer': $route.meta.showFooter}" />
    </keep-alive>
    <router-view class="app-content" v-if="!$route.meta.keepAlive" :class="{'has-footer': $route.meta.showFooter}" />
  </div>
</template>
<script>
import Footer from './components/Footer/Footer'
import PubSub from 'pubsub-js'
export default {
  name: 'App',
  data () {
    return {
      openBbs: 0
    }
  },
  created () {
    if (this.$util.checkApp()) {
      if (!this.$util.getTicket() && this.$util.storage.get('ticket')) {
        this.$util.storage.remove('ticket')
        this.$util.storage.remove('device')
      } else if (this.$util.getTicket()) {
        this.$util.storage.set('ticket', this.$util.getTicket())
        this.$util.storage.set('device', this.$util.getDeviceid())
      }
    } else {
      if (this.$util.cookie.get('login_status') && this.$util.cookie.get('login_status') == 'login') {
        this.$util.storage.set('ticket', this.$util.cookie.get('user_ticket'))
        this.$util.cookie.get('user_device_id') && this.$util.storage.set('device', this.$util.cookie.get('user_device_id'))
      } else if (this.$util.cookie.get('login_status') == 'logout') {
        console.log('清除ticket', this.$util.cookie.get('login_status'))
        this.$util.storage.remove('ticket')
        this.$util.storage.remove('device')
      }
    }
    this.getIndexConfig()
    if (this.$util.storage.get('ticket')) {
      this.getCart()
    }
  },
  methods: {
    async getIndexConfig () {
      let res = await this.$api.getConfig()
      if (!res) return
      this.$global.config = res
      this.$global.city = {
        area_id: res.city.area_id,
        area_name: res.city.area_name
      }
      if (res.config.open_bbs == 1) {
        this.openBbs = 1
      }
      this.changeMainColor(res.config.mobile_head_color)
    },
    changeMainColor (color) {
      let style = `.main-color-bg, .index-wrapper .page-scroll .page-wrapper .img-swiper .img-bullet-active, .index-wrapper .page-scroll .page-wrapper .nav-swiper .nav-bullet-active, .index-wrapper .page-scroll .page-wrapper .activity-box .activity-goods .time-box .list-wrapper .list .item.active, .limit-buy .time-box .list-wrapper .list .item.active{background:${color} !important;}
      .main-color-font, #footer .item.active, .classify .classify-content .nav-box .wrapper .list .item.active .txt{color:${color} !important;}
      .main-color-border, .index-wrapper .header-box .nav-fixed .now-activity, .classify .classify-content .nav-box .wrapper .list .item.active .txt{border-color:${color} !important;}
      .discount-goods .list .item .goods-img .icon .txt{border-color:transparent transparent ${color} !important;`
      var ele = document.createElement('style')
      ele.innerHTML = style
      document.getElementsByTagName('head')[0].appendChild(ele)
    },
    async getCart () {
      let res = await this.$api.getCart({ leader_id: this.$util.storage.get('leader_id') })
      if (!res) return
      let obj = {
        totalPrice: 0,
        totalNum: 0,
        selectNum: 0
      }
      if (res.list && res.list.length > 0) {
        obj.selectNum = res.select_nums
        obj.totalPrice = res.all_money
        obj.totalNum = res.all_nums
        res.list.map(item => {
          obj[item.goods_id] = {
            num: item.cart_nums,
            checked: item.checked
          }
        })
        console.log('3333333333333333333333333333', obj)
        this.$global.goodsNumObj = obj
        let cartInfo = {
          num: res.all_nums,
          selectNum: res.select_nums,
          money: res.all_money,
          allNeedRefresh: true
        }
        PubSub.publish('cartInfo', cartInfo)
      }
    }
  },
  components: {
    Footer
  }
}
</script>
<style lang="stylus">
#app
  -webkit-font-smoothing antialiased
  -moz-osx-font-smoothing grayscale
  color #000
  width 100%
  height 100%
  font-size 12px
  position relative
  z-index 5
  .app-content
    overflow hidden
    height 100%
    box-sizing border-box
    @media only screen and (device-width: 375px) and (device-height: 812px) and (-webkit-device-pixel-ratio: 3)
      padding-bottom 30px
    @media only screen and (device-width: 414px) and (device-height: 896px) and (-webkit-device-pixel-ratio:3)
      padding-bottom 30px
    @media only screen and (device-width: 414px) and (device-height: 896px) and (-webkit-device-pixel-ratio:2)
      padding-bottom 30px
    &.has-footer
      height calc(100% - 46px)
      padding-bottom 0
      @media only screen and (device-width: 375px) and (device-height: 812px) and (-webkit-device-pixel-ratio: 3)
        height calc(100% - 76px)
      @media only screen and (device-width: 414px) and (device-height: 896px) and (-webkit-device-pixel-ratio:3)
        height calc(100% - 76px)
      @media only screen and (device-width: 414px) and (device-height: 896px) and (-webkit-device-pixel-ratio:2)
        height calc(100% - 76px)
</style>
